        /// <summary>
    ///
    /// </summary>
    public static str computedPurchaseOrderNumber()
    {
        str transIdExpr =
        SysComputedColumn::returnField(viewStr(SBProjTransPostingLatestView),
            identifierStr(ProjPostedTransTable), fieldStr(ProjPostedTransTable, TransId));

        str inventTransIdExpr =
        SysComputedColumn::returnField(viewStr(SBProjTransPostingLatestView),
            identifierStr(ProjPostedTransTable), fieldStr(ProjPostedTransTable, InventTransId));

        // NOTE: Use the real D365FO table/field names for PO lines in your environment.
        // In D365FO, PO lines are typically in PurchLine (not "purchaseorderlines").
        // Map PurchId/LineNumber to your target output columns.

        return strFmt(@"
        COALESCE(
            (SELECT TOP 1 pl.PURCHID
               FROM PURCHLINE pl
              WHERE pl.PROJTRANSID = %1
              ORDER BY pl.RECID DESC),
            (SELECT TOP 1 pl2.PURCHID
               FROM PURCHLINE pl2
              WHERE pl2.INVENTTRANSID = %2
              ORDER BY pl2.RECID DESC)
        )",
        transIdExpr,
        inventTransIdExpr);
    }

    public static str computedPurchaseOrderLineNumber()
    {
        str transIdExpr =
        SysComputedColumn::returnField(viewStr(SBProjTransPostingLatestView),
            identifierStr(ProjPostedTransTable), fieldStr(ProjPostedTransTable, TransId));

        str inventTransIdExpr =
        SysComputedColumn::returnField(viewStr(SBProjTransPostingLatestView),
            identifierStr(ProjPostedTransTable), fieldStr(ProjPostedTransTable, InventTransId));

        return strFmt(@"
        COALESCE(
            (SELECT TOP 1 pl.LINENUMBER
               FROM PURCHLINE pl
              WHERE pl.PROJTRANSID = %1
              ORDER BY pl.RECID DESC),
            (SELECT TOP 1 pl2.LINENUMBER
               FROM PURCHLINE pl2
              WHERE pl2.INVENTTRANSID = %2
              ORDER BY pl2.RECID DESC)
        )",
        transIdExpr,
        inventTransIdExpr);
    }
